sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    //var entDocs = api.data.look_up_a_single_record_2.result.individual._reference;
     var entDocs;
     if(api.data.look_up_a_single_record_1.result.kyc_case._reference.customer_type.value=='entity')
     entDocs = api.data.look_up_a_single_record_2.result.entity._reference;
     else
     entDocs = api.data.look_up_a_single_record_2.result.individual._reference;


    var docsList = Object.values(entDocs) // get values only
        .filter(doc => doc.value) // remove null / empty ones
        .map((doc, index) => {
            let fileNameWithoutExt = doc.displayValue.replace(/\.[^/.]+$/, ""); // remove extension
            return {
                id: index + 1,
                label: fileNameWithoutExt,
                value: doc.value

            };
        });
    var link = "/ann?id=attachment_viewer&attachment_id=" + docsList[0].value;
    api.setState("imageLink", link);
    api.setState('dropDownValue', JSON.stringify(docsList));
    api.setState('attachmentSysId', docsList[0].value);
}
